<?php require 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(strlen($name)<2||strlen($name)>100||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Valid name, email and password (8+ characters) required.';else{try{$s=$db->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);go('login.php');}catch(PDOException $e){$error='Email already exists.';}}}head('Register');?><section class="form"><h1>Register</h1><p><?=h($error)?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Name<input name="name" maxlength="100" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button>Create account</button></form></section><?php foot();?>
